"use client";
import React, { useEffect, useState } from "react";
import { getCookie, setCookie } from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import Breadcrumb from "@/components/header/breadcrumb";
import Pagination from "../pagination/pagination";
import Menu from "./menu";
import { useRouter, useSearchParams } from "next/navigation";
import { getBookings } from "@/services/booking/list";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faChevronRight } from "@fortawesome/free-solid-svg-icons";

const pillBase =
  "tw-inline-block tw-rounded-full tw-px-2.5 tw-py-1 tw-text-[11px] tw-font-semibold tw-capitalize";

const green = "tw-bg-[#eafaf0] tw-text-[#1f8a4c]";
const amber = "tw-bg-[#fef6e7] tw-text-[#b7791f]";
const red = "tw-bg-[#fdecec] tw-text-[#b23838]";
const blue = "tw-bg-[#e8f1fd] tw-text-[#2563aa]";
const brand = "tw-bg-[#f4eefc] tw-text-[#6a3da4]";
const gray = "tw-bg-[#f0eef4] tw-text-[#6b6577]";

/* apiv3 App\Enums\Booking\BookingStatus — talep ve rezervasyon zincirleri. */
const statusPill: Record<string, string> = {
  open: green,
  pending: brand,
  closed: gray,
  confirmed: green,
  completed: green,
  cancelled: red,
};

/* Ödeme durumu boş gelebilir (talep henüz ödeme aşamasında değil) — o zaman rozet çizilmez. */
const paymentPill: Record<string, string> = {
  pending: amber,
  charged: blue,
  partial: blue,
  paid: green,
  failed: red,
  partially_refunded: brand,
  refunded: red,
};

export default function Page() {
  const [user, setUser] = useState({ email: "", name: "" });
  const [userLoading, setUserLoading] = useState(true);
  const [enquiriesBookingsList, setEnquiriesBookingsList] = useState([]);
  const [dataLoading, setDataLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalData, setTotalData] = useState(0);

  const router = useRouter();

  const searchParams = useSearchParams();
  const listType = searchParams.get("list")?.toString() ?? "";

  const fetchUserDetail = async () => {
    const userData = await getUserDetail({ token: getCookie("auth-token") });
    return userData;
  };

  const pagination = async ({ page }: { page: number }) => {
    scroll(0, 0);
    setDataLoading(true);
    await getBookings({
      token: (await getCookie("auth-token-v3"))!,
      page,
      type: "&type=" + listType,
    }).then((res) => {
      setEnquiriesBookingsList(res.data);
      setTotalData(res.meta.total);
      setDataLoading(false);
    });
  };

  useEffect(() => {
    try {
      fetchUserDetail().then((res: any) => {
        setUser({ email: res.email, name: res.name });
        setUserLoading(false);
      });

      pagination({ page: 1 });
    } catch (e) {}
  }, []);

  return (
    <main className="tw-font-display">
      <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6">
        <Breadcrumb items={[{ pageTitle: "Profile", pageUrl: "/profile" }]} />
        <h1 className="tw-mt-2 tw-mb-5 tw-text-[clamp(22px,2.6vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
          Bookings &amp; Enquiries
        </h1>

        <div className="tw-grid tw-grid-cols-1 tw-gap-6 md:tw-grid-cols-[260px_minmax(0,1fr)]">
          <div>
            <Menu />
          </div>
          <div>
            <div className="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]">
              {dataLoading && (
                <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 tw-py-16 tw-text-[#5d556c]">
                  <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
                  <p className="tw-m-0 tw-text-sm">Loading. Please wait.</p>
                </div>
              )}
              {!dataLoading && enquiriesBookingsList.length === 0 && (
                <div className="tw-py-12 tw-text-center tw-text-sm tw-text-[#6b6577]">
                  No records found to display
                </div>
              )}
              {!dataLoading && enquiriesBookingsList.length > 0 && (
                <div className="tw-overflow-x-auto">
                  <table className="tw-w-full tw-border-collapse tw-text-sm">
                    <thead>
                      <tr className="tw-bg-[#f7f5fb] tw-text-left tw-text-[11px] tw-uppercase tw-tracking-wide tw-text-[#6b6577]">
                        <th className="tw-px-4 tw-py-3 tw-font-semibold">Reference ID</th>
                        <th className="tw-px-4 tw-py-3 tw-font-semibold">Type</th>
                        <th className="tw-px-4 tw-py-3 tw-font-semibold">Tour Name</th>
                        <th className="tw-px-4 tw-py-3 tw-font-semibold">Start Date</th>
                        <th className="tw-px-4 tw-py-3 tw-font-semibold">Status</th>
                        <th className="tw-px-4 tw-py-3 tw-font-semibold">Payment Status</th>
                        <th className="tw-px-4 tw-py-3 tw-font-semibold">Created At</th>
                        <th className="tw-px-4 tw-py-3 tw-font-semibold"></th>
                      </tr>
                    </thead>
                    <tbody>
                      {enquiriesBookingsList.map((item: any) => (
                        <tr
                          key={item.id}
                          className="tw-cursor-pointer tw-border-0 tw-border-t tw-border-solid tw-border-[#f0edf5] tw-text-[#3f3a4d] tw-transition-colors hover:tw-bg-[#faf9fc]"
                          onClick={() => {
                            router.push(
                              "/booking/" + item.reference_id + "?token=" + item.token,
                            );
                          }}
                        >
                          <td className="tw-px-4 tw-py-3 tw-font-semibold tw-text-[#14101c]">
                            {item.reference_id}
                          </td>
                          <td className="tw-px-4 tw-py-3">
                            <span className={`${pillBase} ${item.record_type === "booking" ? brand : gray}`}>
                              {item.record_type_label}
                            </span>
                          </td>
                          <td className="tw-px-4 tw-py-3">{item.tour?.name || item.subject}</td>
                          <td className="tw-px-4 tw-py-3">{item.start_date || "-"}</td>
                          <td className="tw-px-4 tw-py-3">
                            <span className={`${pillBase} ${statusPill[item.booking_status] || gray}`}>
                              {item.booking_status_label}
                            </span>
                          </td>
                          <td className="tw-px-4 tw-py-3">
                            {item.payment_status ? (
                              <span className={`${pillBase} ${paymentPill[item.payment_status] || gray}`}>
                                {item.payment_status_label}
                              </span>
                            ) : (
                              <span className="tw-text-slate-400">—</span>
                            )}
                          </td>
                          <td className="tw-px-4 tw-py-3 tw-whitespace-nowrap">{item.created_at}</td>
                          <td className="tw-px-4 tw-py-3 tw-text-right tw-text-[#9b95a8]">
                            <FontAwesomeIcon icon={faChevronRight} className="tw-text-xs" />
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>

            {!dataLoading && (
              <div className="tw-mt-5">
                <Pagination
                  currentPage={currentPage}
                  totalCount={totalData}
                  pageSize="10"
                  onPageChange={(page: number) => {
                    setCurrentPage(page);
                    pagination({ page });
                  }}
                />
              </div>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}
