import { apiClient } from "@/lib/apiClient";

// apiv3 Account: GET /bookings — login'li kullanıcının kendi rezervasyonları (sanctum).
// `token` = auth-token-v3 (apiv3 sanctum bearer). Yanıt {data, meta}.
export async function getBookings({
  token,
  page,
  type = "&type=",
}: {
  token: string;
  page: number;
  type: string;
}) {
  return apiClient(`/bookings?page=${page}${type}`, {
    auth: "sanctum",
    token,
  });
}
